//! Mainnet programs and accounts captured into `fixtures/mainnet/` (regenerated by
//! `scripts/dump-mainnet-fixtures.py`) and loaded into LiteSVM as-is.

use super::*;
use flate2::read::GzDecoder;
use litesvm::LiteSVM;
use solana_account::Account as SvmAccount;
use std::io::Read;

include!("../fixtures/mainnet/snapshot.rs");

/// Unix time the clock is pinned to: the snapshot's own block time. Every captured timestamp
/// (klend deposit-cap windows, Orca reward updates) is at or before it, and klend, which accrues
/// interest by elapsed time inside supply and redeem, sees at most seconds to accrue, so its
/// exchange rate matches the capture.
pub const FIXTURE_UNIX_TIMESTAMP: i64 = SNAPSHOT_UNIX_TIMESTAMP;

macro_rules! account_fixture {
    ($key:literal) => {
        ($key, include_bytes!(concat!("../fixtures/mainnet/", $key, ".acct")).as_slice())
    };
}

