const KLEND_ELF_GZ: &[u8] = include_bytes!("../fixtures/mainnet/klend.so.gz");
const JUPITER_ELF_GZ: &[u8] = include_bytes!("../fixtures/mainnet/jupiter.so.gz");
const WHIRLPOOL_ELF_GZ: &[u8] = include_bytes!("../fixtures/mainnet/whirlpool.so.gz");

fn gunzip(bytes: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    GzDecoder::new(bytes).read_to_end(&mut out).unwrap();
    out
}

/// Loads Kamino klend, Jupiter v6 and Orca Whirlpool with every captured account, and pins the
/// clock to [`FIXTURE_UNIX_TIMESTAMP`].
pub fn load_mainnet(svm: &mut LiteSVM) {
    svm.add_program(super::kamino::KLEND, &gunzip(KLEND_ELF_GZ)).unwrap();
    svm.add_program(super::jupiter::JUPITER, &gunzip(JUPITER_ELF_GZ)).unwrap();
    svm.add_program(super::jupiter::WHIRLPOOL, &gunzip(WHIRLPOOL_ELF_GZ)).unwrap();
    for (key, blob) in ACCOUNTS {
        let owner = Pubkey::new_from_array(blob[..32].try_into().unwrap());
        let lamports = u64::from_le_bytes(blob[32..40].try_into().unwrap());
        let account = SvmAccount { lamports, data: blob[41..].to_vec(), owner, executable: blob[40] == 1, rent_epoch: 0 };
        svm.set_account(key.parse().unwrap(), account).unwrap();
    }
    let mut clock = svm.get_sysvar::<Clock>();
    clock.unix_timestamp = FIXTURE_UNIX_TIMESTAMP;
    svm.set_sysvar(&clock);
}
